import { useState } from 'react';
import './App.css';
import { AuthProvider, useAuth } from './context/AuthContext';
import LoginPage from './pages/LoginPage';
import PendingPage from './pages/PendingPage';
import AdminPage from './pages/AdminPage';
import SingleCheck from './components/SingleCheck';
import Dashboard from './pages/Dashboard';
import BulkVerify from './components/BulkVerify';

function AppInner() {
  const { user, loading, logout } = useAuth();
  const [tab, setTab]       = useState('dashboard');
  const [showAdmin, setShowAdmin] = useState(false);

  if (loading) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg)' }}>
        <span className="spinner" style={{ fontSize: 24, color: 'var(--text-dim)' }}>↻</span>
      </div>
    );
  }

  if (!user) return <LoginPage />;
  if (user.status === 'pending') return <PendingPage />;
  if (user.status === 'suspended') return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg)', flexDirection: 'column', gap: 16 }}>
      <div style={{ fontSize: 32 }}>⛔</div>
      <div style={{ fontFamily: 'Syne', fontSize: 18, fontWeight: 700 }}>Account suspended</div>
      <div style={{ color: 'var(--text-muted)', fontSize: 13 }}>Contact an admin to restore access.</div>
      <button className="btn-ghost" onClick={logout}>Sign out</button>
    </div>
  );
  if (user.status === 'banned') return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg)', flexDirection: 'column', gap: 16 }}>
      <div style={{ fontSize: 32 }}>🚫</div>
      <div style={{ fontFamily: 'Syne', fontSize: 18, fontWeight: 700 }}>Account banned</div>
      <div style={{ color: 'var(--text-muted)', fontSize: 13 }}>This account has been permanently banned.</div>
      <button className="btn-ghost" onClick={logout}>Sign out</button>
    </div>
  );

  if (showAdmin && ['admin', 'main_admin'].includes(user.role)) {
    return <AdminPage onBack={() => setShowAdmin(false)} />;
  }

  return (
    <div style={{ minHeight: '100vh', background: 'var(--bg)' }}>
      {/* Nav */}
      <div style={{ borderBottom: '1px solid var(--border)', background: 'rgba(255,255,255,0.85)', backdropFilter: 'blur(12px)', position: 'sticky', top: 0, zIndex: 10 }}>
        <div style={{ maxWidth: 820, margin: '0 auto', padding: '0 28px', height: 56, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{ width: 30, height: 30, background: 'var(--accent)', borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontSize: 14 }}>✉</div>
            <span style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 16, letterSpacing: '-0.02em' }}>MailClean</span>
            <span style={{ background: 'var(--bg3)', border: '1px solid var(--border-mid)', borderRadius: 5, padding: '1px 7px', fontSize: 10, fontFamily: 'DM Mono', color: 'var(--text-dim)' }}>v2.0</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <div style={{ display: 'flex', gap: 5, alignItems: 'center' }}>
              <div style={{ width: 7, height: 7, borderRadius: '50%', background: '#22c55e' }}></div>
              <span style={{ fontSize: 12, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>Live</span>
            </div>
            <div style={{ width: 1, height: 16, background: 'var(--border-mid)' }} />
            <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>{user.name}</span>
            {['admin', 'main_admin'].includes(user.role) && (
              <button onClick={() => setShowAdmin(true)}
                style={{ background: 'var(--amber-bg)', color: 'var(--amber)', border: '1px solid var(--amber-border)', padding: '5px 12px', borderRadius: 7, fontSize: 11, fontFamily: 'Syne', fontWeight: 600, cursor: 'pointer' }}>
                Admin ↗
              </button>
            )}
            <button className="btn-ghost" onClick={logout} style={{ padding: '6px 14px', fontSize: 12 }}>Sign out</button>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: 820, margin: '0 auto', padding: '0 28px 80px' }}>
        {/* Hero */}
        <div style={{ padding: '48px 0 36px', textAlign: 'center' }}>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, background: 'var(--bg3)', border: '1px solid var(--border-mid)', borderRadius: 20, padding: '5px 14px', marginBottom: 18, fontSize: 11, color: 'var(--text-muted)', fontFamily: 'DM Mono', letterSpacing: '0.04em' }}>
            SMTP · MX · CATCH-ALL · DISPOSABLE · RISK SCORING
          </div>
          <h1 style={{ fontSize: 40, fontWeight: 700, letterSpacing: '-0.04em', lineHeight: 1.1, marginBottom: 12 }}>
            Know if your email lands<br />
            <span style={{ color: 'var(--text-dim)' }}>before you hit send.</span>
          </h1>
          <p style={{ color: 'var(--text-muted)', fontSize: 14, maxWidth: 400, margin: '0 auto' }}>
            Full deliverability check in seconds. Stop burning sends on dead addresses.
          </p>
        </div>

        {/* Tabs */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 28, justifyContent: 'center' }}>
          {[{ id: 'dashboard', label: '📊 Dashboard' }, { id: 'single', label: 'Single check' }, { id: 'bulk', label: 'Bulk verify' }].map(t => (
            <button key={t.id} onClick={() => setTab(t.id)}
              style={{
                background: tab === t.id ? 'var(--accent)' : 'var(--bg2)',
                color: tab === t.id ? '#fff' : 'var(--text-muted)',
                border: `1px solid ${tab === t.id ? 'var(--accent)' : 'var(--border-mid)'}`,
                padding: '11px 26px', borderRadius: 'var(--radius)',
                fontFamily: 'Syne', fontWeight: 600, fontSize: 13,
                boxShadow: tab === t.id ? 'var(--shadow-md)' : 'var(--shadow-sm)',
              }}>{t.label}</button>
          ))}
        </div>

        {tab === 'dashboard' ? (
          <Dashboard />
        ) : (
          <div className="card animate-in" key={tab} style={{ padding: '36px 40px' }}>
            {tab === 'single' && <SingleCheck />}
            {tab === 'bulk' && <BulkVerify />}
          </div>
        )}

        {/* Stats */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 12, marginTop: 20 }}>
          {[
            { value: '2k–8k/hr', label: 'Verification speed', sub: 'with 30 threads' },
            { value: '6 checks', label: 'Detection layers', sub: 'per email address' },
            { value: '50,000', label: 'Max batch size', sub: 'emails per upload' },
          ].map(s => (
            <div key={s.label} style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '18px 22px', boxShadow: 'var(--shadow-sm)' }}>
              <div style={{ fontFamily: 'Syne', fontSize: 22, fontWeight: 700, letterSpacing: '-0.03em', marginBottom: 2 }}>{s.value}</div>
              <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{s.label}</div>
              <div style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'DM Mono', marginTop: 1 }}>{s.sub}</div>
            </div>
          ))}
        </div>

        <div style={{ marginTop: 36, paddingTop: 20, borderTop: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between' }}>
          <span style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'DM Mono' }}>api.brainboxecomlab.com</span>
          <span style={{ fontSize: 11, color: 'var(--text-dim)' }}>MailClean © {new Date().getFullYear()}</span>
        </div>
      </div>
    </div>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <AppInner />
    </AuthProvider>
  );
}
